import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'en'

  const languages = acceptLanguage.split(',').map((part) => {
    const [tag, ...params] = part.trim().split(';')
    const qParam = params.find((p) => p.trim().startsWith('q='))
    const q = qParam ? Number.parseFloat(qParam.trim().slice(2)) : 1
    return { tag: tag.trim(), q }
  })

  languages.sort((a, b) => b.q - a.q)

  return languages[0]?.tag ?? 'en'
}

export default async function Home() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const themeCookie = cookieStore.get('theme')
  const theme = themeCookie?.value ?? 'light'

  const acceptLanguage = headersList.get('accept-language')
  const language = getPreferredLanguage(acceptLanguage)

  return (
    <main>
      <h1>User Preferences</h1>
      <p>Current theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </main>
  )
}

